import React, { useState } from 'react';
import './Technologies.css';

const TECH_CATEGORIES = [
  {
    id: 'frontend',
    label: 'FRONTEND ENGINEERING',
    title: 'Frontend Engineering',
    skills: [
      { name: 'VUE.JS', icon: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/vuejs/vuejs-original.svg' },
      { name: 'REACT', icon: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/react/react-original.svg' },
      { name: 'JAVASCRIPT', icon: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/javascript/javascript-original.svg' },
      { name: 'TYPESCRIPT', icon: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/typescript/typescript-original.svg' },
      { name: 'NUXT.JS', icon: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/nuxtjs/nuxtjs-original.svg' },
      { name: 'NEXT.JS', icon: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/nextjs/nextjs-original-wordmark.svg' },
      { name: 'TAILWIND CSS', icon: 'https://www.vectorlogo.zone/logos/tailwindcss/tailwindcss-icon.svg' },
      { name: 'VITE', icon: 'https://upload.wikimedia.org/wikipedia/commons/f/f1/Vitejs-logo.svg' },
      { name: 'BOOTSTRAP', icon: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/bootstrap/bootstrap-original.svg' },
    ]
  },
  {
    id: 'backend',
    label: 'BACKEND ENGINEERING',
    title: 'Backend Engineering',
    skills: [
      { name: 'NODE.JS', icon: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/nodejs/nodejs-original.svg' },
      { name: 'EXPRESS', icon: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/express/express-original.svg' },
      { name: 'PYTHON', icon: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/python/python-original.svg' },
      { name: 'GO', icon: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/go/go-original-wordmark.svg' },
      { name: 'PHP', icon: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/php/php-original.svg' },
    ]
  },
  {
    id: 'mobile',
    label: 'MOBILE APPLICATION DEVELOPMENT',
    title: 'Mobile Development',
    skills: [
      { name: 'REACT NATIVE', icon: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/react/react-original.svg' },
      { name: 'FLUTTER', icon: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/flutter/flutter-original.svg' },
      { name: 'SWIFT', icon: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/swift/swift-original.svg' },
      { name: 'KOTLIN', icon: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/kotlin/kotlin-original.svg' },
    ]
  },
  {
    id: 'design',
    label: 'DESIGN',
    title: 'Design',
    skills: [
      { name: 'FIGMA', icon: 'https://www.vectorlogo.zone/logos/figma/figma-icon.svg' },
      { name: 'ILLUSTRATOR', icon: 'https://www.vectorlogo.zone/logos/adobe_illustrator/adobe_illustrator-icon.svg' },
      { name: 'AFTER EFFECTS', icon: 'https://www.vectorlogo.zone/logos/adobe_aftereffects/adobe_aftereffects-icon.svg' },
      { name: 'BLENDER', icon: 'https://www.vectorlogo.zone/logos/blender/blender-icon.svg' },
    ]
  },
  {
    id: 'database',
    label: 'DATA & BACKEND PLATFORMS',
    title: 'Data & Backend Platforms',
    skills: [
      { name: 'POSTGRESQL', icon: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/postgresql/postgresql-original.svg' },
      { name: 'MONGODB', icon: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/mongodb/mongodb-original.svg' },
      { name: 'REDIS', icon: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/redis/redis-original.svg' },
      { name: 'FIREBASE', icon: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/firebase/firebase-plain.svg' },
    ]
  },
  {
    id: 'cloud',
    label: 'CLOUD',
    title: 'Cloud & Infrastructure',
    skills: [
      { name: 'AWS', icon: 'https://www.vectorlogo.zone/logos/amazon_aws/amazon_aws-icon.svg' },
      { name: 'GCP', icon: 'https://www.vectorlogo.zone/logos/google_cloud/google_cloud-icon.svg' },
      { name: 'DOCKER', icon: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/docker/docker-original.svg' },
      { name: 'KUBERNETES', icon: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/kubernetes/kubernetes-plain.svg' },
    ]
  },
];

export default function Technologies() {
  const [activeTab, setActiveTab] = useState(TECH_CATEGORIES[0].id);
  const activeCategory = TECH_CATEGORIES.find(cat => cat.id === activeTab);

  return (
    <section className="py-section border-t border-black">
      <div className="container">
        <h2 className="font-display text-4xl font-bold mb-12">Technologies</h2>

        <div className="flex border border-black min-h-[600px] flex-col md:flex-row">
          {/* Sidebar */}
          <div className="w-full md:w-64 border-b md:border-b-0 md:border-r border-black flex flex-col bg-gray-50">
            {TECH_CATEGORIES.map((cat) => (
              <button
                key={cat.id}
                onClick={() => setActiveTab(cat.id)}
                className={`text-left px-4 py-4 text-[11px] font-bold tracking-widest uppercase transition-colors border-b border-black last:border-b-0 ${
                  activeTab === cat.id ? 'bg-white' : 'hover:bg-gray-100 text-gray-500'
                }`}
              >
                {cat.label}
              </button>
            ))}
          </div>

          {/* Content Area */}
          <div className="flex-1 p-8 md:p-12">
            <h3 className="font-display text-3xl font-bold mb-10">{activeCategory.title}</h3>

            <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 border-l border-t border-black">
              {activeCategory.skills.map((skill) => (
                <div 
                  key={skill.name}
                  className="aspect-square border-r border-b border-black flex flex-col items-center justify-center p-4 group hover:bg-gray-50 transition-colors"
                >
                  <div className="w-12 h-12 mb-4 flex items-center justify-center">
                    <img 
                      src={skill.icon} 
                      alt={skill.name} 
                      className="max-w-full max-h-full grayscale group-hover:grayscale-0 transition-all duration-300"
                    />
                  </div>
                  <span className="text-[10px] font-bold tracking-tighter text-center">{skill.name}</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}
